class Animal:
    def __init__(self, name):
        self.name = name

    def eat(self):
        print(self.name + " is eating!")


class Dog(Animal):
    def fetch(self):
        print(self.name + " brings the ball back!")

class Animal:
    def speak(self):
        print("Some sound.")

class Dog(Animal):
    def speak(self):
        print("Woof!")

class Cow(Animal):
    pass

Dog().speak()   # Woof!       (Dog's own version)
Cow().speak()   # Some sound. (nothing to override it, so the parent's)

