class Bird:
    def __init__(self, name):
        self.name = name

    def fly(self):
        print(self.name + " is flying high!")

    def speak(self):
        print(self.name + " makes a sound.")


class Parrot(Bird):
    def speak(self):
        print(self.name + " wants a cracker!")


polly = Parrot("Polly")
polly.fly()     # inherited from Bird
polly.speak()   # Parrot's own version wins

